#!/usr/bin/env node
// Generates the canonical (UNC) Lua stubs from aliases.json and marks the old names deprecated in rimkit.lua.
// Run: node tools/gen-unc-stubs.js   (also run by `npm run gen` and before packaging)
//
// Input:  aliases.json (copied from src/api/aliases.json by the native CMake step)
// Output: stubs/rimkit_unc.lua (generated, do not edit)
//         stubs/rimkit.lua gets one `---@deprecated` line above each old function. The step is idempotent.
const fs = require("fs");
const path = require("path");

const root = path.join(__dirname, "..");
const aliases = JSON.parse(fs.readFileSync(path.join(root, "aliases.json"), "utf8"));
const stubPath = path.join(root, "stubs", "rimkit.lua");
const outPath = path.join(root, "stubs", "rimkit_unc.lua");

function expand() {
  const rules = [];
  for (const g of aliases.groups) {
    for (const entry of g.names) {
      const gt = entry.indexOf(">");
      const oldName = gt >= 0 ? entry.slice(0, gt) : entry;
      const newName = gt >= 0 ? entry.slice(gt + 1) : entry;
      const oldPath = `${g.from}.${oldName}`;
      const newPath = newName.includes(".") ? `game.${newName}` : `${g.to}.${newName}`;
      rules.push({ oldPath, newPath, deprecate: g.deprecate !== false && oldPath !== newPath, group: g.to });
    }
  }
  return rules;
}

const rules = expand();
const lines = fs.readFileSync(stubPath, "utf8").split(/\r?\n/);

// Find `function a.b.c(args) end` lines with the annotation block above them.
const defs = new Map();
for (let i = 0; i < lines.length; i++) {
  const m = /^function ([\w.]+)\((.*)\) end\s*$/.exec(lines[i]);
  if (!m) continue;
  let start = i;
  while (start > 0 && /^---/.test(lines[start - 1])) start--;
  defs.set(m[1], { line: i, annotations: lines.slice(start, i), params: m[2] });
}

// 1. Mark old names deprecated in rimkit.lua (idempotent).
const insertBefore = new Map();
for (const r of rules) {
  if (!r.deprecate) continue;
  const d = defs.get(r.oldPath);
  if (!d) continue;
  const above = lines[d.line - 1] || "";
  if (/@deprecated/.test(above)) continue;
  insertBefore.set(d.line, `---@deprecated Use ${r.newPath} (works until ${aliases.removed_in}). Run: rimkit migrate --write`);
}
const patched = [];
lines.forEach((l, i) => {
  if (insertBefore.has(i)) patched.push(insertBefore.get(i));
  patched.push(l);
});
if (patched.length !== lines.length) {
  fs.writeFileSync(stubPath, patched.join("\n"));
}

// 2. Emit canonical stubs.
const out = [];
out.push("-- Generated by tools/gen-unc-stubs.js from aliases.json. Do not edit.");
out.push("-- Canonical RimKit names (UNC). The old names are deprecated, see rimkit.lua.");
out.push("---@meta");
out.push("");
const emitted = new Set();
const body = [];
for (const r of rules) {
  if (emitted.has(r.newPath)) continue;
  emitted.add(r.newPath);
  const d = defs.get(r.oldPath);
  const annotations = d ? d.annotations.filter((a) => !/@deprecated/.test(a)) : [];
  const params = d ? d.params : "...";
  body.push(...annotations);
  body.push(`function ${r.newPath}(${params}) end`);
  body.push("");
}
// Declare parent tables (everything but the final segment of each path).
const parents = new Set();
for (const p of emitted) {
  const parts = p.split(".");
  for (let i = 2; i < parts.length; i++) parents.add(parts.slice(0, i).join("."));
}
const ordered = [...parents].sort((a, b) => a.split(".").length - b.split(".").length || a.localeCompare(b));
for (const t of ordered) out.push(`${t} = ${t} or {}`);
out.push("");
out.push(...body);
fs.writeFileSync(outPath, out.join("\n"));
console.log(`gen-unc-stubs: ${emitted.size} canonical names, ${insertBefore.size} deprecations added`);
